import sys
input = sys.stdin.readline

n, m = map(int, input().split())
clauses = [list(map(int, input().split())) for _ in range(m)]

adj = [[] for _ in range(2 * n + 1)]

def node(literal):
    return 2 * literal - 1 if literal > 0 else -2 * literal

for a, b in clauses:
    adj[node(-a)].append(node(b))
    adj[node(-b)].append(node(a))
radj = [[] for _ in range(2 * n + 1)]
for u in range(1, 2 * n + 1):
    for v in adj[u]:
        radj[v].append(u)
order = []
seen = [False] * (2 * n + 1)
pos = [0] * (2 * n + 1)
for s in range(1, 2 * n + 1):
    if seen[s]:
        continue
    seen[s] = True
    stack = [s]
    while stack:
        v = stack[-1]
        if pos[v] < len(adj[v]):
            w = adj[v][pos[v]]
            pos[v] += 1
            if not seen[w]:
                seen[w] = True
                stack.append(w)
        else:
            order.append(v)
            stack.pop()
comp = [-1] * (2 * n + 1)
comp_count = 0
for s in reversed(order):
    if comp[s] != -1:
        continue
    comp[s] = comp_count
    stack = [s]
    while stack:
        v = stack.pop()
        for w in radj[v]:
            if comp[w] == -1:
                comp[w] = comp_count
                stack.append(w)
    comp_count += 1
print("yes" if all(comp[2 * x - 1] != comp[2 * x] for x in range(1, n + 1)) else "no")

